mapper.select:
SELECT s.student_id
FROM students s
JOIN teachers t ON s.grade = t.grade AND s.class_name = t.class_name
WHERE t.teacher_id     = #{teacherId}
AND s.student_number = #{studentNumber}

mapper.update:
UPDATE COUPONS
SET
    name = #{name},
    coupon_point = #{couponPoint}
WHERE coupon_no = #{couponNo}

UPDATE coupon_purchase
SET purchase_state = 'USED'
WHERE coupon_purchase_no = #{couponPurchaseNo}
  AND student_id = #{studentId}
  AND purchase_state = 'NOT_USED'
